scenario.ru:
// Оценка 40 px при медиане 180 px — что сделает скроллбар?
const virtualizer = useVirtualizer({
  count: comments.length,        // 5 000
  getScrollElement: () => parentRef.current,
  estimateSize: () => 40,        // реальные строки: 40..600 px, медиана ~180
  overscan: 5,
});
// строки: ref={virtualizer.measureElement}, позиция через translateY(v.start)

evidence.en:
{virtualizer.getVirtualItems().map((v) => (
  <div
    key={v.index}                     // <-- suspect A
    ref={virtualizer.measureElement}
    data-index={v.index}
    style={{ transform: `translateY(${v.start}px)` }}
  >
    <Row item={orders[v.index]} />    // Row holds: const [selected, setSelected] = useState(false)  <-- suspect B
  </div>
))}

